package de.davscha.characterfun.i18n

import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.setValue
import java.util.Locale

/** Sprachen der Oberfläche. [promptName] ist der Name der Sprache für die Anweisung an das Modell. */
enum class AppLanguage(val tag: String, val label: String, val promptName: String, val locale: Locale) {
    DE("de-DE", "Deutsch", "Deutsch", Locale.GERMANY),
    EN("en-US", "English", "Englisch", Locale.US),
    ES("es-ES", "Español", "Spanisch", Locale("es", "ES")),
    FR("fr-FR", "Français", "Französisch", Locale.FRANCE),
}

/**
 * Übersetzung der Oberfläche. Der deutsche Text ist zugleich der Schlüssel – so bleibt der Code
 * lesbar, und fehlt eine Übersetzung, steht einfach der deutsche Text da.
 * Weil [lang] ein Compose-State ist, schaltet die Oberfläche sofort um, ohne Neustart.
 */
object I18n {
    var lang by mutableStateOf(AppLanguage.DE)
}

/** Übersetzt [de] in die aktuelle Sprache; %s-Platzhalter werden mit [args] gefüllt. */
fun tr(de: String, vararg args: Any?): String {
    val lang = I18n.lang
    val text = if (lang == AppLanguage.DE) de else TABLE[de]?.getOrNull(lang.ordinal - 1) ?: de
    return if (args.isEmpty()) text else runCatching { text.format(*args) }.getOrDefault(text)
}

